 "content": "def transform(grid):
    """Fill the cells strictly between consecutive marker cells in each row/column."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = next(v for row in grid for v in row if v != grid[0][0])
    fill = 3
    for r in range(h):
        xs = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(xs, xs[1:]):
            for c in range(a + 1, b):
                out[r][c] = fill
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(ys, ys[1:]):
            for r in range(a + 1, b):
                out[r][c] = fill
    return out
